presets.css:
.chat-thread {
  /* 字体与头像尺寸 */
  --dress-bubble-font-size: 14px;
  --dress-bubble-avatar-size: 32px;
  --dress-bubble-avatar-radius: 50%;
}

.chat-msg {
  position: relative !important;
  margin-bottom: 10px !important;
}

/* ===== 气泡基础：细长 + 四角偏方 + 半透 ===== */
.chat-bubble {
  font-size: 14px !important;
  padding: 6px 14px !important;
  border-radius: 14px !important;   /* 整体圆角变小，四角偏方 */
  position: relative !important;
  line-height: 1.4 !important;
  overflow: hidden !important;

  /* 雾面核心：背景模糊 + 饱和度提升 */
  backdrop-filter: blur(10px) saturate(170%) !important;
  -webkit-backdrop-filter: blur(10px) saturate(170%) !important;

  /* 细腻高光边，加强气泡边缘 */
  border: 1px solid rgba(255, 255, 255, 0.65) !important;

  /* 柔和投影，营造微悬浮感 */
  box-shadow:
    0 6px 18px -8px rgba(0, 30, 50, 0.12),
    0 0 0 1px rgba(255, 255, 255, 0.3) inset !important;
}

/* 对方气泡：极淡浅蓝 · 50% 透明 · 左下角更方 */
.chat-msg.is-them .chat-bubble {
  background: rgba(210, 232, 252, 0.5) !important;
  background-image: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.55) 0%,
    rgba(200, 228, 250, 0.1) 100%
  ) !important;
  color: #1a2a38 !important;
  border-radius: 14px 14px 14px 2px !important;   /* 左下角更方：2px */
  text-shadow: 0 1px 1px rgba(255, 255, 255, 0.7) !important;
}

/* 我方气泡：极淡浅蓝 · 50% 透明 · 右下角更方 */
.chat-msg.is-me .chat-bubble {
  background: rgba(200, 226, 250, 0.5) !important;
  background-image: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.55) 0%,
    rgba(190, 220, 248, 0.1) 100%
  ) !important;
  color: #16232e !important;
  border-radius: 14px 14px 2px 14px !important;   /* 右下角更方：2px */
  text-shadow: 0 1px 1px rgba(255, 255, 255, 0.65) !important;
}

/* 气泡内左上角高光，增强雾面玻璃质感 */
.chat-bubble::before {
  content: "" !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  width: 65% !important;
  height: 50% !important;
  background: radial-gradient(
    circle at 15% 15%,
    rgba(255, 255, 255, 0.75) 0%,
    rgba(255, 255, 255, 0) 70%
  ) !important;
  border-radius: 50% !important;
  opacity: 0.55 !important;
  pointer-events: none !important;
  z-index: 0 !important;
}

/* 文字置于高光之上，保证清晰 */
.chat-bubble > * {
  position: relative !important;
  z-index: 1 !important;
}
